set-variable.value:
@{
            var key = context.Request.Headers.GetValueOrDefault("x-mcp-key", "");
            if (key == "{{mcp-gateway-key}}") { return "agente"; }
            if (key == "{{mcp-key-panel}}") { return "panel"; }
            return "";
        }

@{
            if (context.Request.Method != "POST") { return ""; }
            JToken body;
            try { body = JToken.Parse(context.Request.Body.As<string>(preserveContent: true)); } catch { return ""; }
            var items = body is JArray ? (IEnumerable<JToken>)body : new JToken[] { body };
            foreach (var item in items) {
                var obj = item as JObject;
                if (obj != null && (((string)obj["method"]) ?? "").ToLowerInvariant() == "tools/call") { return (string)obj.SelectToken("params.name") ?? ""; }
            }
            return "";
        }

@{
            if ((string)context.Variables["auditTool"] == "") { return ""; }
            JToken body;
            try { body = JToken.Parse(context.Request.Body.As<string>(preserveContent: true)); } catch { return ""; }
            var items = body is JArray ? (IEnumerable<JToken>)body : new JToken[] { body };
            foreach (var item in items) {
                var obj = item as JObject;
                if (obj != null && (((string)obj["method"]) ?? "").ToLowerInvariant() == "tools/call") {
                    var text = obj.SelectToken("params.arguments") == null ? "{}" : obj.SelectToken("params.arguments").ToString(Newtonsoft.Json.Formatting.None);
                    return text.Length > 500 ? text.Substring(0, 500) : text;
                }
            }
            return "";
        }

@{
            if (context.Request.Method != "POST") { return ""; }
            var list = "{{mcp-blocked-tools}}".Replace(" ", "").ToLowerInvariant();
            if (list == "" || list == "none") { return ""; }
            JToken body;
            try { body = JToken.Parse(context.Request.Body.As<string>(preserveContent: true)); } catch { return ""; }
            var items = body is JArray ? (IEnumerable<JToken>)body : new JToken[] { body };
            foreach (var item in items) {
                var obj = item as JObject;
                if (obj == null) { continue; }
                if ((((string)obj["method"]) ?? "").ToLowerInvariant() != "tools/call") { continue; }
                var name = (string)obj.SelectToken("params.name");
                if (name == null) { continue; }
                if (("," + list + ",").Contains("," + name.ToLowerInvariant() + ",")) { return name; }
            }
            return "";
        }

return-response.set-body:
@{
                        return new JObject(new JProperty("error", new JObject(
                            new JProperty("code", "AccessBlockedByGateway"),
                            new JProperty("message", "Tool " + (string)context.Variables["blockedTool"] + " of server aviation-mcp is blocked.")))).ToString();
                    }

set-variable.value:
@{
            if (context.Request.Method != "POST") { return "false"; }
            var list = "{{mcp-blocked-tools}}".Replace(" ", "").ToLowerInvariant();
            if (list == "" || list == "none") { return "false"; }
            JToken body;
            try { body = JToken.Parse(context.Request.Body.As<string>(preserveContent: true)); } catch { return "false"; }
            var items = body is JArray ? (IEnumerable<JToken>)body : new JToken[] { body };
            foreach (var item in items) {
                var obj = item as JObject;
                if (obj != null && (((string)obj["method"]) ?? "").ToLowerInvariant() == "tools/list") { return "true"; }
            }
            return "false";
        }

when.set-body:
@{
                    var hidden = "{{mcp-blocked-tools}}".Replace(" ", "").ToLowerInvariant().Split(',');
                    var raw = context.Response.Body.As<string>(preserveContent: true);
                    var sse = context.Response.Headers.GetValueOrDefault("Content-Type", "").Contains("text/event-stream");
                    var lines = sse ? raw.Split('\n') : new string[] { raw };
                    for (int i = 0; i < lines.Length; i++) {
                        var text = sse ? lines[i].TrimEnd('\r') : lines[i];
                        if (sse) {
                            if (!text.StartsWith("data:")) { continue; }
                            text = text.Substring(5).Trim();
                        }
                        JToken msg;
                        try { msg = JToken.Parse(text); } catch { continue; }
                        var items = msg is JArray ? (IEnumerable<JToken>)msg : new JToken[] { msg };
                        foreach (var item in items) {
                            var tools = item.SelectToken("result.tools") as JArray;
                            if (tools == null) { continue; }
                            foreach (var tool in tools.ToList()) {
                                var n = (((string)tool["name"]) ?? "").ToLowerInvariant();
                                if (Array.IndexOf(hidden, n) >= 0) { tool.Remove(); }
                            }
                        }
                        var json = msg.ToString(Newtonsoft.Json.Formatting.None);
                        lines[i] = sse ? "data: " + json : json;
                    }
                    return string.Join("\n", lines);
                }
